import { renderReportPDF } from "./report-pdf-preview.js?v=20261011-report-preview-v2";
const activeInlineReviews = new WeakMap();
// Review the frozen source snapshot and download the already generated bytes.
// Source loading errors never turn a short Saved preview into exported code.
export function openReportExportReview({ prepare, isCurrent, mount = null }) {
  if (mount) activeInlineReviews.get(mount)?.();
  const dialog = document.createElement(mount ? "section" : "dialog");
  dialog.className = `report-export-review${mount ? " report-export-inline" : ""}`;
  const previousChildren = mount ? [...mount.children].map(element => ({ element, hidden: element.hidden })) : [];
  const previousScroll = mount?.scrollTop || 0;
  const previousFocus = document.activeElement;
  if (mount) {
    previousChildren.forEach(({element}) => { element.hidden = true; });
    mount.classList.add("is-previewing-report");
    mount.scrollTop = 0;
  }
  const titleID = `report-export-title-${crypto.randomUUID()}`;
  dialog.setAttribute("aria-labelledby", titleID);
  const header = document.createElement("header");
  const title = document.createElement("h2");
  title.id = titleID;
  title.textContent = "PDF preview";
  const close = document.createElement("button");
  close.type = "button";
  close.className = "report-export-close";
  close.setAttribute("aria-label", "Close export review");
  close.textContent = "← Back to Report";
  header.append(title, close);
  const status = document.createElement("p");
  status.className = "report-export-status";
  status.setAttribute("role", "status");
  const content = document.createElement("section");
  content.className = "report-export-content";
  content.setAttribute("aria-label", "Report export preview");
  const footer = document.createElement("footer");
  const retry = document.createElement("button");
  retry.type = "button";
  retry.textContent = "Try again";
  retry.hidden = true;
  const download = document.createElement("button");
  download.type = "button";
  download.className = "report-export-download";
  download.textContent = "Download PDF";
  download.disabled = true;
  footer.append(retry, download);
  dialog.append(header, status, content, footer);
  let disposed = false;
  let packet = null;
  let disposePreview = () => {};
  const objectURLs = new Set();
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    clearInterval(contextCheck);
    objectURLs.forEach(url => URL.revokeObjectURL(url));
    packet = null;
    disposePreview();
    content.replaceChildren();
    dialog.remove();
    if (mount) {
      if (activeInlineReviews.get(mount) === dispose) activeInlineReviews.delete(mount);
      previousChildren.forEach(({element, hidden}) => { element.hidden = hidden; });
      mount.classList.remove("is-previewing-report");
      mount.scrollTop = previousScroll;
      if (previousFocus?.isConnected) previousFocus.focus({ preventScroll: true });
    }
  };
  const closeReview = () => { if (mount) dispose(); else dialog.close(); };
  const current = () => !disposed && (!mount || mount.isConnected) && isCurrent();
  const contextCheck = setInterval(() => {
    if (!current()) { closeReview(); dispose(); }
  }, 200);
  close.addEventListener("click", closeReview);
  dialog.addEventListener("keydown", event => {
    if (mount && event.key === "Escape") { event.preventDefault(); closeReview(); }
  });
  dialog.addEventListener("close", dispose, { once: true });
  const load = async () => {
    packet = null;
    objectURLs.forEach(url => URL.revokeObjectURL(url));
    objectURLs.clear();
    retry.hidden = true;
    download.disabled = true;
    content.replaceChildren();
    status.setAttribute("role", "status");
    status.textContent = "Loading the saved Report PDF…";
    try {
      if (!current()) { dispose(); return; }
      const prepared = await prepare();
      if (!current()) { dispose(); return; }
      if (!prepared.manifest?.items?.length || !prepared.pdfBlob) throw new Error("The stored Report PDF is unavailable. Please try again.");
      packet = prepared;
      const manifest = packet.manifest;
      status.textContent = `${manifest.project.name} · Version ${manifest.reportVersion || 1}`;
      download.disabled = false;
      disposePreview();
      disposePreview = await renderReportPDF(content, packet.pdfBlob, current);
      if (!current()) disposePreview();
      download.disabled = false;
    } catch (error) {
      if (!current()) { dispose(); return; }
      status.setAttribute("role", "alert");
      status.textContent = error.message || "Could not load the complete source text. Please try again.";
      retry.hidden = false;
    }
  };
  retry.addEventListener("click", () => void load());
  download.addEventListener("click", () => {
    if (!current()) { closeReview(); dispose(); return; }
    if (!packet) return;
    const url = URL.createObjectURL(packet.pdfBlob);
    objectURLs.add(url);
    const link = document.createElement("a");
    link.href = url;
    link.download = packet.filename || "permitext-report.pdf";
    link.click();
    // Keep the reviewed snapshot available for another download until closed.
  });
  (mount || document.body).append(dialog);
  if (mount) { activeInlineReviews.set(mount, dispose); close.focus({ preventScroll: true }); }
  else dialog.showModal();
  void load();
  return dialog;
}
